def minMinutesTakeK(s, k):
    n = len(s)
    total = {'a': 0, 'b': 0, 'c': 0}
    for ch in s:
        total[ch] += 1
    if min(total.values()) < k:
        return -1
    limit = {ch: total[ch] - k for ch in total}
    cnt = {'a': 0, 'b': 0, 'c': 0}
    left = 0
    best = 0
    for right, ch in enumerate(s):
        cnt[ch] += 1
        while cnt[ch] > limit[ch]:
            cnt[s[left]] -= 1
            left += 1
        best = max(best, right - left + 1)
    return n - best
